import './DepositPage.css';
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../Context/AuthContext';

import ApiDeposit from '../../Services/ApiDeposit';  // Thêm import service

const DepositPage = () => {
    const navigate = useNavigate();
    const { user } = useAuth();  // Giả sử AuthContext có user

    // State cho options (mệnh giá)
    const [options] = useState([
        
        { id: 1, price: 10000 },
        { id: 2, price: 20000 },
        { id: 3, price: 30000 },
        { id: 4, price: 50000 },
        { id: 5, price: 100000 },
        { id: 6, price: 200000 },
        { id: 7, price: 500000 },
    ]);  // Có thể fetch từ API nếu cần

    const [selectedId, setSelectedId] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [depositInfo, setDepositInfo] = useState(null);  // Info từ API

    const selected = options.find(opt => opt.id === selectedId);
    const method = "Chuyển khoản ngân hàng";  // Fixed
    const username = user?.accountname || "Chưa đăng nhập";  // Từ AuthContext

    const formatVND = (price) => {
        return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(price);
    };

    const handlePay = async () => {
        if (!selected) return;
        
        setLoading(true);
        setError("");
        
        try {
            // Gọi API tạo deposit
            const data = await ApiDeposit.createDeposit({ amount: selected.price });
            setDepositInfo(data);  // Lưu info để hiển thị QR
            // Có thể navigate hoặc hiển thị modal
        } catch (err) {
            setError("Lỗi tạo yêu cầu nạp tiền: " + (err.response?.data?.detail || err.message));
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container py-4 topup-page">
            <div className="row g-4">
                {/* LEFT: danh sách mệnh giá */}
                <div className="col-lg-7">
                    <div className="card shadow-sm h-100">
                        <div className="card-header bg-white border-0 pt-3 pb-0">
                            <h5 className="mb-3 fw-semibold">QR Pay</h5>
                            <div className="text-muted small">Chọn mệnh giá</div>
                        </div>
                        <div className="card-body">
                            <div className="list-group list-group-flush">
                                {options.map((opt) => {
                                    const active = selectedId === opt.id;
                                    return (
                                        <label
                                            key={opt.id}
                                            className={
                                                "list-group-item d-flex align-items-center justify-content-between pointer " +
                                                (active ? "list-group-item-action active-like" : "list-group-item-action")
                                            }
                                            onClick={() => setSelectedId(opt.id)}
                                        >
                                            <div className="d-flex align-items-center gap-3">
                                                <input
                                                    type="radio"
                                                    className="form-check-input m-0"
                                                    name="price"
                                                    checked={active}
                                                    onChange={() => setSelectedId(opt.id)}
                                                    onClick={(e) => e.stopPropagation()}
                                                />
                                                <span className="fw-500">{formatVND(opt.price)}</span>
                                            </div>
                                        </label>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>

                {/* RIGHT: Chi tiết giao dịch */}
                <div className="col-lg-5">
                    <div className="card shadow-sm h-100">
                        <div className="card-header bg-white border-0 pt-3">
                            <h5 className="mb-0 fw-semibold">Chi tiết giao dịch</h5>
                        </div>
                        <div className="card-body">
                            <div className="d-flex justify-content-between py-2 border-bottom">
                                <span className="text-muted">Sản phẩm được chọn</span>
                                <span className="fw-semibold">
                                    {selected ? formatVND(selected.price) : "Chưa chọn"}
                                </span>
                            </div>
                            <div className="d-flex justify-content-between py-2 border-bottom">
                                <span className="text-muted">Phương thức thanh toán</span>
                                <span className="fw-semibold">{method}</span>
                            </div>
                            <div className="d-flex justify-content-between py-2">
                                <span className="text-muted">Tên tài khoản</span>
                                <span className="fw-semibold">{username}</span>
                            </div>

                            <button
                                className="btn btn-danger w-100 mt-3 py-2 fw-semibold"
                                disabled={!selected || loading}
                                onClick={handlePay}
                            >
                                {loading ? "Đang xử lý..." : "Xử lý thanh toán"}
                            </button>

                            {!selected && (
                                <div className="form-text mt-2">
                                    Hãy chọn một mệnh giá để tiếp tục.
                                </div>
                            )}
                            {error && <p className="text-danger mt-2">{error}</p>}
                        </div>
                    </div>
                </div>
            </div>

            {/* Hiển thị QR sau khi tạo deposit */}
            {depositInfo && (
                <div className="mt-4">
                    <h5>Thông tin chuyển khoản</h5>
                    <p>Mã giao dịch: {depositInfo.transaction_code}</p>
                    <img src={depositInfo.qr_code_url} alt="QR Code" />
                    <p>Tài khoản: {depositInfo.bank_info.account}</p>
                    <p>Tên: {depositInfo.bank_info.name}</p>
                    <p>Ngân hàng: {depositInfo.bank_info.bank}</p>
                    <p>Nội dung: {depositInfo.transaction_code}</p>
                </div>
            )}
        </div>
    );
};

export default DepositPage;
